// src/common/validate_vectors.rs handles vector validation for payload-only collections
pub fn validate_vector_dimensions(...) {
    match operation {
        PointInsertOperationsInternal::PointsBatch(batch) => {
            validate_batch_vectors(&batch.vectors, vectors_config)?;
        }
        // ...
    }
}

// For payload-only collections (vectors_config.empty()),
// attempting to insert vectors returns 'Not existing vector name error'
// This is by-design: payload-only collections support payload CRUD only.
